import java.io.*;
import java.util.*;

public class tr0_variant2 {
    private static final int MOD = 998244353;

    public static void main(String[] args) throws Exception {
        InputReader in = new InputReader(System.in);
        int n = in.nextInt();
        long k = in.nextLong();

        if (k >= n) {
            System.out.println(0);
            return;
        }

        long[] factorial = new long[n + 1];
        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = factorial[i - 1] * i % MOD;
        }

        if (k == 0) {
            System.out.println(factorial[n]);
            return;
        }

        int c = n - (int) k;
        long result = factorial[n];
        result = result * modInverse(factorial[c]) % MOD;
        result = result * modInverse(factorial[n - c]) % MOD;

        long total = 0;
        for (int i = 0; i <= c; i++) {
            long comb = factorial[c] * modInverse(factorial[i]) % MOD;
            comb = comb * modInverse(factorial[c - i]) % MOD;
            long power = modPow(c - i, n);
            long term = comb * power % MOD;
            if (i % 2 == 0) {
                total = (total + term) % MOD;
            } else {
                total = (total - term + MOD) % MOD;
            }
        }

        result = result * total % MOD * 2 % MOD;
        System.out.println(result);
    }

    private static long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return res;
    }

    private static long modInverse(long a) {
        return modPow(a, MOD - 2);
    }

    static class InputReader {
        private BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public InputReader(String file) throws IOException {
            br = new BufferedReader(new FileReader(file));
        }

        private String readToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        public String next() throws IOException {
            return readToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(readToken());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(readToken());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(readToken());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public char nextChar() throws IOException {
            return readToken().charAt(0);
        }

        public boolean ready() throws IOException {
            return br.ready();
        }

        public void delay(int ms) throws InterruptedException {
            Thread.sleep(ms);
        }
    }
}
